import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, DirectionalLight } = THREE;

  const root = new Group();
  root.name = 'footer-colophon';

  const colors = (config.intent?.visualSpec?.colors) ?? config.visual?.colors ?? {
    background: '#0b0b10',
    surface: '#101015',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#121218' }, { at: 1, hex: '#0b0b10' }],
  };

  const disposables = [];
  const timelines = [];

  function hexVec3(hex) {
    const c = new Color(hex);
    return vec3(c.r, c.g, c.b);
  }

  // ---------- BAND (backdrop) ----------
  const bandW = 6.8;
  const bandH = 2.0;
  const topStop = colors.gradientStops?.[0]?.hex ?? '#121218';
  const bottomStop = colors.gradientStops?.[1]?.hex ?? '#0b0b10';

  const bandGeo = new PlaneGeometry(bandW, bandH, 1, 1);
  const bandMat = new MeshStandardNodeMaterial();
  bandMat.colorNode = mix(hexVec3(bottomStop), hexVec3(topStop), uv().y);
  bandMat.roughness = 0.6;
  bandMat.metalness = 0.2;
  bandMat.transparent = true;
  bandMat.opacity = 0;
  const band = new Mesh(bandGeo, bandMat);
  band.position.set(0, 0, 0);
  root.add(band);
  disposables.push(bandGeo, bandMat);

  // ---------- HAIRLINE RULES ----------
  function makeHairline(y) {
    const geo = new PlaneGeometry(bandW, 0.006, 1, 1);
    const mat = new MeshStandardNodeMaterial();
    mat.color = new Color('#23232b');
    mat.roughness = 0.35;
    mat.metalness = 0.6;
    mat.transparent = true;
    mat.opacity = 0;
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, y, 0.01);
    root.add(mesh);
    disposables.push(geo, mat);
    return mesh;
  }
  const hairlineTop = makeHairline(0.95);
  const hairlineBottom = makeHairline(-0.6);

  // ---------- ACCENT BAR ----------
  const accentGeo = new PlaneGeometry(0.3, 0.02, 1, 1);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.color = new Color(colors.accent ?? '#ff2a38');
  accentMat.emissive = new Color(colors.accent ?? '#ff2a38');
  accentMat.emissiveIntensity = 1.4;
  accentMat.roughness = 0.5;
  accentMat.metalness = 0.3;
  accentMat.transparent = true;
  accentMat.opacity = 0;
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(-3.2 + 0.15, 0.42, 0.01);
  root.add(accentBar);
  disposables.push(accentGeo, accentMat);

  // ---------- LIGHTING (local, per doctrine) ----------
  const rimLight = new DirectionalLight(0xffffff, 0.7);
  rimLight.position.set(-4, 3, 5);
  rimLight.target = band;
  root.add(rimLight);
  root.add(rimLight.target);

  // ---------- TEXT CONTENT PARSING ----------
  const items = config.textContent ?? config.intent?.visualSpec?.visualSpec?.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const paper = colors.paper ?? '#e8ecf2';
  const legalColor = '#c7c9d1';

  let wordmarkItem = null;
  let legalItem = null;
  const columns = [];
  let currentColumn = null;

  for (const item of items) {
    if (!item) continue;
    if (item.role === 'wordmark') {
      wordmarkItem = item;
    } else if (item.role === 'column-header') {
      currentColumn = { header: item, links: [] };
      columns.push(currentColumn);
    } else if (item.role === 'link') {
      if (currentColumn) currentColumn.links.push(item);
    } else if (item.role === 'legal') {
      legalItem = item;
    }
  }

  const leftX = -3.3;
  const colXs = [leftX + 2.0 + 0.375, leftX + 2.0 + 0.375 + 1.2 + 0.375, leftX + 2.0 + 0.375 + (1.2 + 0.375) * 2];

  const textObjects = [];

  // wordmark
  if (wordmarkItem) {
    const t = wordmarkItem.typography ?? {};
    const wm = ctx.fontAtlas.createText(wordmarkItem.text, {
      fontSize: t.fontSize ?? 34,
      color: paper,
      align: 'left',
      letterSpacingPx: (t.letterSpacing ?? 0.02) * (t.fontSize ?? 34),
    });
    wm.position.set(leftX, 0.75, 0.02);
    root.add(wm);
    textObjects.push(wm);
  }

  // columns
  const headerY = 0.7;
  const linkYs = [headerY - 0.3, headerY - 0.55, headerY - 0.8];

  columns.forEach((col, ci) => {
    const x = colXs[ci];
    const ht = col.header.typography ?? {};
    const headerObj = ctx.fontAtlas.createText(col.header.text, {
      fontSize: ht.fontSize ?? 9,
      color: paper,
      align: 'left',
      letterSpacingPx: (ht.letterSpacing ?? 0.12) * (ht.fontSize ?? 9),
    });
    headerObj.position.set(x, headerY, 0.02);
    root.add(headerObj);
    textObjects.push(headerObj);

    col.links.forEach((link, li) => {
      const lt = link.typography ?? {};
      const linkObj = ctx.fontAtlas.createText(link.text, {
        fontSize: lt.fontSize ?? 13,
        color: paper,
        align: 'left',
        letterSpacingPx: (lt.letterSpacing ?? 0) * (lt.fontSize ?? 13),
      });
      linkObj.position.set(x, linkYs[li] ?? (headerY - 0.3 * (li + 1)), 0.02);
      root.add(linkObj);
      textObjects.push(linkObj);

      // hover interaction: paper -> accent
      linkObj.userData.handlers = linkObj.userData.handlers ?? {};
      const baseColor = new Color(paper);
      const hoverColor = new Color(colors.accent ?? '#ff2a38');
      const applyColor = (c) => {
        linkObj.traverse((child) => {
          if (child.material && child.material.color) {
            child.material.color.copy(c);
          }
        });
      };
      linkObj.userData.handlers.onPointerEnter = () => {
        gsap.to({}, {
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          onUpdate: () => {},
        });
        applyColor(hoverColor);
        gsap.to(linkObj.position, { z: 0.04, duration: 0.14, ease: 'power2.out' });
      };
      linkObj.userData.handlers.onPointerLeave = () => {
        applyColor(baseColor);
        gsap.to(linkObj.position, { z: 0.02, duration: 0.14, ease: 'power2.out' });
      };
    });
  });

  // legal line
  if (legalItem) {
    const lt = legalItem.typography ?? {};
    const legalObj = ctx.fontAtlas.createText(legalItem.text, {
      fontSize: lt.fontSize ?? 9,
      color: legalColor,
      align: 'left',
      letterSpacingPx: (lt.letterSpacing ?? 0.04) * (lt.fontSize ?? 9),
    });
    legalObj.position.set(leftX, -0.88, 0.02);
    root.add(legalObj);
    textObjects.push(legalObj);
  }

  // ---------- ENTRANCE ANIMATION (fade-up, single set object) ----------
  const fadeMaterials = [bandMat, hairlineTop.material, hairlineBottom.material, accentMat];
  root.position.y = 0.2;

  const tl = gsap.timeline();
  timelines.push(tl);
  tl.to(root.position, {
    y: 0,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  fadeMaterials.forEach((mat) => {
    tl.to(mat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  });

  // text objects: fade via material opacity if available
  textObjects.forEach((obj) => {
    obj.traverse((child) => {
      if (child.material) {
        child.material.transparent = true;
        const targetOpacity = child.material.opacity ?? 1;
        child.material.opacity = 0;
        tl.to(child.material, { opacity: targetOpacity, duration: 0.5, ease: 'power2.out' }, 0);
      }
    });
  });

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    textObjects.forEach((obj) => {
      obj.traverse((child) => {
        if (child.geometry && typeof child.geometry.dispose === 'function') child.geometry.dispose();
        if (child.material && typeof child.material.dispose === 'function') child.material.dispose();
      });
    });
    root.clear();
  };

  return root;
}
